// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint256 fundAmount, bool willRevert) public {
        fundAmount = bound(fundAmount, 0, 1 ether);

        AttackerRecipient r = new AttackerRecipient(willRevert);

        vm.deal(address(this), fundAmount);

        (bool sent, ) = address(c).call{value: fundAmount}("");
        require(sent);

        vm.assume(fundAmount > 0);

        bool ok;
        try c.withdrawAll(address(r)) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 bal = address(c).balance;
        assertTrue((ok && bal == 0) || (!ok && bal == fundAmount));
    }
}

contract AttackerRecipient {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    fallback() external payable {
        if (shouldRevert) revert("revert fallback");
    }
}
